        var_set_str(vm, "KEEPSMALLER", out);
        var_set_str(vm, "SMALLFILES", out);
        var_set_str(vm, "SIZELE", out);
        var_set_num(vm, "KEEPSMALLER_N", kept);
        var_set_num(vm, "KEEPSMALLER_DROP", drop);
        var_set_num(vm, "KEEPSMALLER_BYTES", lim);
