      var_set_num(vm, "COPYALL_BYTES", bytes);
      var_set_num(vm, "COPYALL_MISS", miss);
      var_set_num(vm, "COPYALL_FAIL", failc);
      var_set_num(vm, "COPYALL_SCAN", nscan);
      var_set_num(vm, "OK", failc == 0 ? 1 : 0);
