      var_set_num(vm, "MEDIANKV_N", n);
      var_set_num(vm, "MEDIANKV_KEYS", keys);
      var_set_num(vm, "P50KV_N", n);
      var_set_num(vm, "MIDKV_N", n);
      var_set_num(vm, "OK", 1);
