      snprintf(op, sizeof op, "%s", L->cur.text);
      for (char *q = op; *q; q++)
        if (*q >= 'a' && *q <= 'z') *q = (char)(*q - 'a' + 'A');
      if (strcmp(op, "BOTKEY") == 0 || strcmp(op, "ARGMINKV") == 0 ||
          strcmp(op, "MINKEY") == 0 || strcmp(op, "KEYMIN") == 0 ||
          strcmp(op, "LEASTKEY") == 0 || strcmp(op, "RAREST") == 0)
        want_min = 1;
