      snprintf(vm->last_str, sizeof vm->last_str, "%s", out);
      vm->last_n = lines;
      var_set_num(vm, "LAST_N", lines);
      var_set_num(vm, "CUTALL_N", lines);
      var_set_num(vm, "CUTALL_HIT", hits);
      var_set_num(vm, "OK", 1);
