      if (!removed) {
        /* keep original bag */
        snprintf(out, sizeof out, "%s", bag);
      }
      var_set_str(vm, "LAST", out);
      snprintf(vm->last_str, sizeof vm->last_str, "%s", out);
      vm->last_n = removed;
      var_set_num(vm, "LAST_N", removed);
      var_set_num(vm, "REMOVE_N", removed);
      var_set_num(vm, "OK", 1);
      bump(vm); return 1;
