    snprintf(vm->last_str, sizeof vm->last_str, "%s", hr.str);
    vm->last_n = hr.n;
    var_set_num(vm, "LAST_N", hr.n);
    var_set_str(vm, "SETBYVAL", hr.str);
    var_set_str(vm, "REPLACEVAL", hr.str);
    var_set_num(vm, "SETBYVAL_N", hr.n);
    var_set_num(vm, "REPLACEVAL_N", hr.n);
